-- Seller trust and shipping transaction fixtures; never books a carrier or pays.
begin;
create temporary table th_delivery_results(stage text,result text) on commit drop;
create function pg_temp.th_delivery_claim(uid uuid) returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','aal','aal1')::text,true);end$$;
create function pg_temp.th_delivery_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'DELIVERY ASSERT FAILED: %',label;end if;end$$;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data)
select ('99000000-7a21-4000-8000-'||lpad(n::text,12,'0'))::uuid,'delivery-fixture-'||n||'@example.invalid',now(),jsonb_build_object('name','Public seller '||n) from generate_series(1,4)n;
do $$declare uid uuid;begin for uid in select id from auth.users where id::text like '99000000-7a21-%' loop perform pg_temp.th_delivery_claim(uid);perform public.th_api('snapshot');end loop;end$$;
update public.th_shops set status='verified',reviewed_at=public.th_now() where user_id in ('99000000-7a21-4000-8000-000000000001','99000000-7a21-4000-8000-000000000003');
do $$declare seller uuid:='99000000-7a21-4000-8000-000000000001';buyer uuid:='99000000-7a21-4000-8000-000000000002';seller2 uuid:='99000000-7a21-4000-8000-000000000003';outsider uuid:='99000000-7a21-4000-8000-000000000004';
 shop1 uuid;shop2 uuid;photo1 text;photo2 text;item1 uuid;item2 uuid;oid uuid;sample_oid uuid;legacy_oid uuid;reply jsonb;state jsonb;sale jsonb;shipping jsonb;original jsonb;before_at bigint;begin
 select id into shop1 from public.th_shops where user_id=seller;select id into shop2 from public.th_shops where user_id=seller2;
 photo1:=seller::text||'/99000000-7a21-4000-8000-000000000099.png';photo2:=seller2::text||'/99000000-7a21-4000-8000-000000000099.png';
 insert into storage.objects(bucket_id,name,owner_id,metadata) values('product-photos',photo1,seller::text,'{"mimetype":"image/png","size":1024}'),('product-photos',photo2,seller2::text,'{"mimetype":"image/png","size":1024}');
 perform pg_temp.th_delivery_claim(seller);perform public.th_api('upload_register',jsonb_build_object('path',photo1));perform pg_temp.th_delivery_claim(seller2);perform public.th_api('upload_register',jsonb_build_object('path',photo2));
 insert into public.th_products(shop_id,title,description,category,condition,location,image_path,price,mode) values(shop1,'Shipping first item','Shipping regression fixture','home','สภาพดี','Bangkok',photo1,100,'fixed') returning id into item1;
 insert into public.th_products(shop_id,title,description,category,condition,location,image_path,price,mode) values(shop2,'Shipping private second item','Shipping regression fixture','home','สภาพดี','Bangkok',photo2,200,'fixed') returning id into item2;
 perform set_config('request.jwt.claims','{}',true);state:=public.th_api('snapshot');select v into reply from jsonb_array_elements(state->'stores')x(v) where v->>'id'=shop1::text;
 perform pg_temp.th_delivery_assert(state->'shipping'='true'::jsonb and reply->>'displayName'='Public seller 1' and reply->'joinedAt'<>'null'::jsonb and (reply->>'completedSales')::int=0 and reply->'reviewedAt'<>'null'::jsonb,'public seller name, join date, review date and honest completed count');
 perform pg_temp.th_delivery_assert(position('delivery-fixture-1@example.invalid' in reply::text)=0 and not(reply?'phone') and not(reply?'details'),'public seller profile never exposes email or verification documents');
 select v into reply from jsonb_array_elements(state->'stores')x(v) where v->>'id'='closet';perform pg_temp.th_delivery_assert(reply->'isDemo'='true'::jsonb and reply->'completedSales'='null'::jsonb and reply->'joinedAt'='null'::jsonb,'fictional store never gets fabricated trust stats');
 perform pg_temp.th_delivery_claim(buyer);
 begin perform public.th_api('reserve',jsonb_build_object('productIds',jsonb_build_array(item1),'delivery','shipping','requestKey','shipping-invalid-order'));raise exception 'Shipping without recipient accepted';exception when sqlstate 'PT400' then null;end;
 shipping:=jsonb_build_object('delivery','shipping','recipientName','PRIVATE_RECIPIENT_FIXTURE','phone','0812345678','address','PRIVATE_ADDRESS_ORIGINAL 123 fixture road Bangkok');
 original:=shipping||jsonb_build_object('productIds',jsonb_build_array(item1,item2),'requestKey','shipping-multishop-order');reply:=public.th_api('reserve',original);oid:=(reply->>'orderId')::uuid;
 state:=public.th_api('snapshot');select v into reply from jsonb_array_elements(state->'orders')x(v) where v->>'id'=oid::text;
 perform pg_temp.th_delivery_assert(reply->>'delivery'='shipping' and reply#>>'{deliveryInfo,recipientName}'='PRIVATE_RECIPIENT_FIXTURE','buyer sees own shipping details');
 begin perform public.th_api('reserve',original||'{"address":"CHANGED_RETRY_ADDRESS fixture road"}'::jsonb);raise exception 'Changed initial retry accepted';exception when sqlstate 'PT409' then null;end;
 shipping:=shipping||'{"address":"PRIVATE_ADDRESS_UPDATED 456 fixture road Bangkok"}'::jsonb;perform public.th_api('order_delivery',shipping||jsonb_build_object('orderId',oid));perform public.th_api('reserve',original);
 perform pg_temp.th_delivery_assert((select address=shipping->>'address' and delivery='shipping' from public.th_order_delivery where order_id=oid),'original reserve retry preserves later address changes');
 perform pg_temp.th_delivery_claim(seller);reply:=public.th_api('sales');select v into sale from jsonb_array_elements(reply->'sales')x(v) where v->>'id'=oid::text;perform pg_temp.th_delivery_assert(sale->'deliveryInfo'='null'::jsonb,'seller address hidden until simulated payment');
 reply:=public.th_api('order_messages',jsonb_build_object('orderId',oid,'shopId',shop1));perform pg_temp.th_delivery_assert(reply->'deliveryInfo'='null'::jsonb,'unpaid seller chat hides address');
 perform pg_temp.th_delivery_claim(outsider);state:=public.th_api('snapshot');perform pg_temp.th_delivery_assert(position('PRIVATE_ADDRESS' in state::text)=0,'other buyer cannot read recipient details');
 begin perform public.th_api('order_delivery',shipping||jsonb_build_object('orderId',oid));raise exception 'Outsider changed delivery';exception when sqlstate 'PT404' then null;end;
 perform set_config('request.jwt.claims','{}',true);state:=public.th_api('snapshot');perform pg_temp.th_delivery_assert(position('PRIVATE_ADDRESS' in state::text)=0 and position('0812345678' in state::text)=0,'public snapshot contains no recipient information');
 insert into pg_temp.th_delivery_results values('Public seller facts and private recipient details with immutable reservation retries','PASS');
 perform pg_temp.th_delivery_claim(buyer);reply:=public.th_api('pay',jsonb_build_object('orderId',oid,'method','qr_demo','outcome','success','requestKey','shipping-real-payment'));perform pg_temp.th_delivery_assert((reply#>>'{payment,amount}')::int=300,'shipping choice never changes server item total or adds hidden fee');
 begin perform public.th_api('order_delivery',shipping||jsonb_build_object('orderId',oid));raise exception 'Paid recipient edited';exception when sqlstate 'PT409' then null;end;
 perform pg_temp.th_delivery_claim(seller);reply:=public.th_api('sales');select v into sale from jsonb_array_elements(reply->'sales')x(v) where v->>'id'=oid::text;
 perform pg_temp.th_delivery_assert(sale#>>'{deliveryInfo,address}'=shipping->>'address' and (sale->>'subtotal')::int=100 and jsonb_array_length(sale->'items')=1 and position('Shipping private second item' in sale::text)=0,'participating paid seller gets required recipient but only own items and subtotal');
 begin perform public.th_api('order_ship',jsonb_build_object('orderId',oid,'shopId',shop1,'carrier','Demo Carrier','trackingNumber','DEMO-ONE'));raise exception 'Shipment before ready accepted';exception when sqlstate 'PT409' then null;end;
 perform public.th_api('fulfill',jsonb_build_object('orderId',oid,'shopId',shop1,'status','preparing'));perform public.th_api('fulfill',jsonb_build_object('orderId',oid,'shopId',shop1,'status','ready'));
 begin perform public.th_api('order_handoff',jsonb_build_object('orderId',oid,'shopId',shop1));raise exception 'Shipping seller bypassed shipment';exception when sqlstate 'PT409' then null;end;
 begin perform public.th_api('order_ship',jsonb_build_object('orderId',oid,'shopId',shop2,'carrier','Demo Carrier','trackingNumber','DEMO-OTHER'));raise exception 'Seller shipped other store';exception when sqlstate 'PT404' then null;end;
 perform pg_temp.th_delivery_claim(buyer);
 begin perform public.th_api('order_handoff',jsonb_build_object('orderId',oid,'shopId',shop1));raise exception 'Buyer received before shipped';exception when sqlstate 'PT409' then null;end;
 perform pg_temp.th_delivery_claim(seller);reply:=public.th_api('order_ship',jsonb_build_object('orderId',oid,'shopId',shop1,'carrier','Demo Carrier','trackingNumber','DEMO-ONE'));before_at:=(reply#>>'{handoff,shipment,shippedAt}')::bigint;perform pg_temp.th_delivery_assert(reply#>'{handoff,shipment,isDemo}'='false'::jsonb and reply#>'{handoff,shipment,isManual}'='true'::jsonb,'actual seller shipment is manual tracking, independently of simulated payment');
 reply:=public.th_api('order_ship',jsonb_build_object('orderId',oid,'shopId',shop1,'carrier','Demo Carrier','trackingNumber','DEMO-ONE'));perform pg_temp.th_delivery_assert((reply#>>'{handoff,shipment,shippedAt}')::bigint=before_at,'same shipment retry is immutable');
 begin perform public.th_api('order_ship',jsonb_build_object('orderId',oid,'shopId',shop1,'carrier','Demo Carrier','trackingNumber','DEMO-CHANGED'));raise exception 'Tracking overwritten';exception when sqlstate 'PT409' then null;end;
 perform pg_temp.th_delivery_claim(buyer);reply:=public.th_api('order_messages',jsonb_build_object('orderId',oid,'shopId',shop1));perform pg_temp.th_delivery_assert(reply->'canConfirm'='true'::jsonb and reply#>>'{handoff,shipment,trackingNumber}'='DEMO-ONE','buyer sees shipment and can acknowledge receipt');
 perform public.th_api('order_handoff',jsonb_build_object('orderId',oid,'shopId',shop1));perform pg_temp.th_delivery_assert((select status='sold' from public.th_products where id=item1) and (select status='reserved' from public.th_products where id=item2),'shipping completion changes own shop products only');
 perform pg_temp.th_delivery_claim(seller2);perform public.th_api('fulfill',jsonb_build_object('orderId',oid,'shopId',shop2,'status','preparing'));perform public.th_api('fulfill',jsonb_build_object('orderId',oid,'shopId',shop2,'status','ready'));perform public.th_api('order_ship',jsonb_build_object('orderId',oid,'shopId',shop2,'carrier','Demo Carrier','trackingNumber','DEMO-TWO'));
 perform pg_temp.th_delivery_claim(buyer);perform public.th_api('order_handoff',jsonb_build_object('orderId',oid,'shopId',shop2));perform pg_temp.th_delivery_assert((select status='completed' from public.th_orders where id=oid),'all shipments acknowledged complete actual order');
 state:=public.th_api('snapshot');select v into reply from jsonb_array_elements(state->'stores')x(v) where v->>'id'=shop1::text;perform pg_temp.th_delivery_assert((reply->>'completedSales')::int=1,'completed seller count derived from sold product rows');
 insert into pg_temp.th_delivery_results values('Paid multi-shop shipping, immutable tracking, seller ownership and buyer acknowledgement','PASS');
 reply:=public.th_api('reserve','{"productIds":["p15"],"delivery":"pickup","requestKey":"shipping-sample-order"}');sample_oid:=(reply->>'orderId')::uuid;perform public.th_api('order_delivery',shipping||jsonb_build_object('orderId',sample_oid));
 reply:=public.th_api('pay',jsonb_build_object('orderId',sample_oid,'method','card_demo','outcome','success','requestKey','shipping-sample-payment'));state:=public.th_api('snapshot');select v into reply from jsonb_array_elements(state->'orders')x(v) where v->>'id'=sample_oid::text;
 perform pg_temp.th_delivery_assert(reply->>'delivery'='shipping' and reply#>'{shipment,isDemo}'='true'::jsonb and left(reply#>>'{shipment,trackingNumber}',5)='DEMO-','sample checkout auto creates explicitly simulated shipment');
 perform public.th_api('sample_complete',jsonb_build_object('orderId',sample_oid));perform pg_temp.th_delivery_assert((select status='completed' from public.th_sample_orders where id=sample_oid),'sample shipping receipt can complete');
 insert into pg_temp.th_delivery_results values('Unified sample shipping and simulated delivery completion','PASS');
 insert into public.th_orders(user_id,total,request_key,payload,payment_required) values(buyer,75,'shipping-legacy-fixture-order','{}',false) returning id into legacy_oid;
 insert into public.th_products(shop_id,title,description,category,condition,location,image_path,price,mode,status,reserved_order_id) values(shop1,'Legacy shipping item','Legacy shipping regression fixture','home','สภาพดี','Bangkok',photo1,75,'fixed','reserved',legacy_oid) returning id into item1;
 insert into public.th_order_items values(legacy_oid,item1,shop1,'Legacy shipping item',75);
 perform public.th_api('order_delivery',shipping||jsonb_build_object('orderId',legacy_oid));
 perform pg_temp.th_delivery_assert((select payment_required and delivery='shipping' from public.th_orders where id=legacy_oid),'legacy pickup order gains payment step when selecting shipping');

end$$;
set local role authenticated;
do $$begin
 begin perform 1 from public.th_order_delivery;raise exception 'Direct address readable';exception when insufficient_privilege then null;end;
 begin perform 1 from public.th_order_shipments;raise exception 'Direct shipments readable';exception when insufficient_privilege then null;end;
 begin perform public.th_delivery_info('99000000-7a21-4000-8000-000000000001');raise exception 'Private delivery helper exposed';exception when insufficient_privilege then null;end;
 begin perform public.th_api_v7_base('snapshot');raise exception 'Old dispatcher exposed';exception when insufficient_privilege then null;end;
end$$;
reset role;
select stage,result from pg_temp.th_delivery_results;
rollback;
